# Let me try: Cell becomes 3 if it's a 0 next to a non-zero, OR a non-zero next to a different non-zero
# i.e., bridges or boundaries between different non-zero values

def transform_bridge_boundary(grid):
    result = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])

    for r in range(rows):
        for c in range(cols):
            becomes_three = False

            if grid[r][c] == 0:
                # Zero becomes 3 if it touches a non-zero horizontally
                if (c > 0 and grid[r][c-1] != 0) or (c < cols-1 and grid[r][c+1] != 0):
                    becomes_three = True
            else:
                # Non-zero becomes 3 if it touches a different non-zero horizontally
                if (c > 0 and grid[r][c-1] != 0 and grid[r][c-1] != grid[r][c]) or \
                   (c < cols-1 and grid[r][c+1] != 0 and grid[r][c+1] != grid[r][c]):
                    becomes_three = True

            if becomes_three:
                result[r][c] = 3
    return result

