# Let me also try including vertical neighbors
def transform_bridge_boundary_vertical(grid):
    result = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])

    for r in range(rows):
        for c in range(cols):
            becomes_three = False

            if grid[r][c] == 0:
                # Zero becomes 3 if it touches a non-zero in any horizontal/vertical direction
                neighbors = []
                if r > 0: neighbors.append(grid[r-1][c])
                if r < rows-1: neighbors.append(grid[r+1][c])
                if c > 0: neighbors.append(grid[r][c-1])
                if c < cols-1: neighbors.append(grid[r][c+1])
                if any(n != 0 for n in neighbors):
                    becomes_three = True
            else:
                # Non-zero becomes 3 if it touches a different non-zero in any direction
                neighbors = []
                if r > 0: neighbors.append(grid[r-1][c])
                if r < rows-1: neighbors.append(grid[r+1][c])
                if c > 0: neighbors.append(grid[r][c-1])
                if c < cols-1: neighbors.append(grid[r][c+1])
                has_diff_nonzero = any(n != 0 and n != grid[r][c] for n in neighbors)
                if has_diff_nonzero:
                    becomes_three = True

            if becomes_three:
                result[r][c] = 3
    return result

